+import {
+    ValidationArguments,
+    ValidationOptions,
+    registerDecorator,
+    ValidatorConstraint,
+    ValidatorConstraintInterface,
+} from 'class-validator';
+import { CreateDimensionDto, overageAllowedEnum, PricingTier } from './create-dimension.dto.js';
+
+const numericStringPattern = /^(0|[1-9]\d*)(\.\d+)?$/;
+const integerStringPattern = /^\d+$/;
+
+function isValidPrice(value: unknown): value is string {
+    return (
+        typeof value === 'string' &&
+        numericStringPattern.test(value) &&
+        (value.split('.')[1]?.length ?? 0) <= 8
+    );
+}
+
+export function getTierValidationError(dimension: Partial<CreateDimensionDto>): string | undefined {
+    const { tiers } = dimension;
+    if (tiers === undefined || tiers === null) {
+        return undefined;
+    }
+    if (!Array.isArray(tiers) || tiers.length === 0) {
+        return 'tiers must contain at least one tier';
+    }
+    if (dimension.usageEntitlement !== undefined && dimension.usageEntitlement !== null) {
+        return 'tiers cannot be combined with usageEntitlement';
+    }
+    if (dimension.consumptionPrice !== undefined && dimension.consumptionPrice !== null) {
+        return 'tiers cannot be combined with consumptionPrice';
+    }
+    if (dimension.overageAllowed === overageAllowedEnum.true) {
+        return 'tiers cannot be combined with overageAllowed set to true';
+    }
+
+    const usageIncrement = Number(dimension.usageIncrement);
+    if (!Number.isInteger(usageIncrement) || usageIncrement <= 0) {
+        return 'usageIncrement must be a positive integer for tiered dimensions';
+    }
+
+    const positions = new Set<string>();
+    for (const tier of tiers) {
+        if (!tier || !integerStringPattern.test(tier.tierPosition)) {
+            return 'tierPosition must be a numeric integer string';
+        }
+        if (positions.has(tier.tierPosition)) {
+            return 'tierPosition values must be unique';
+        }
+        positions.add(tier.tierPosition);
+        if (tier.unitPrice !== undefined && !isValidPrice(tier.unitPrice)) {
+            return 'unitPrice must be a non-negative numeric string with no more than 8 decimal places';
+        }
+    }
+
+    const sortedTiers = [...tiers].sort((a, b) => Number(a.tierPosition) - Number(b.tierPosition));
+    let previousBound = 0;
+    for (let index = 0; index < sortedTiers.length; index += 1) {
+        const tier = sortedTiers[index];
+        if (index > 0 && tier.unitPrice === undefined) {
+            return 'Every tier after the first requires unitPrice';
+        }
+        if (tier.upperBound === 'inf') {
+            if (index !== sortedTiers.length - 1) {
+                return 'Only the final tier may have an upperBound of inf';
+            }
+            continue;
+        }
+        if (!numericStringPattern.test(tier.upperBound)) {
+            return 'upperBound must be a numeric string or inf';
+        }
+        const upperBound = Number(tier.upperBound);
+        if (upperBound <= previousBound) {
+            return 'Tier upperBound values must increase without overlap';
+        }
+        if (!Number.isInteger(upperBound / usageIncrement)) {
+            return 'Tier upperBound values must align to usageIncrement';
+        }
+        previousBound = upperBound;
+    }
+
+    return undefined;
+}
+
+@ValidatorConstraint({ name: 'ValidPricingTiers', async: false })
+export class ValidPricingTiersRule implements ValidatorConstraintInterface {
+    validate(_tiers: PricingTier[] | null, args: ValidationArguments) {
+        return getTierValidationError(args.object as CreateDimensionDto) === undefined;
+    }
+
+    defaultMessage(args: ValidationArguments) {
+        return getTierValidationError(args.object as CreateDimensionDto) ?? 'Invalid pricing tiers';
+    }
+}
+
+export function ValidPricingTiers(validationOptions?: ValidationOptions) {
+    return function (object: unknown, propertyName: string) {
+        registerDecorator({
+            name: 'ValidPricingTiers',
+            target: object.constructor,
+            propertyName,
+            options: validationOptions,
+            validator: ValidPricingTiersRule,
+        });
+    };
+}
